
CREATE OR REPLACE VIEW analytics.vw_geography_performance AS SELECT g.market, g.order_country, g.order_region, g.order_state, g.order_city, COUNT(DISTINCT f.order_id) AS total_orders, COUNT(DISTINCT f.order_item_id) AS total_order_items, SUM(f.quantity) AS total_units_sold, ROUND(SUM(f.sales), 2) AS total_recorded_sales, ROUND(SUM(f.discount), 2) AS total_discounts, ROUND(SUM(f.order_item_total), 2) AS total_net_item_value, ROUND(SUM(f.order_item_total) / NULLIF(COUNT(DISTINCT f.order_id), 0), 2) AS average_order_value FROM analytics.fact_order_items f INNER JOIN analytics.dim_geography g ON f.geography_key = g.geography_key GROUP BY g.market, g.order_country, g.order_region, g.order_state, g.order_city;
